#!/usr/bin/env bash
set -Eeuo pipefail
repo_dir=$(cd -- "$(dirname -- "$0")/.." && pwd)
source_dir=$(realpath "${1:?Usage: bash scripts/test.sh MODDED_SOURCE_DIR}")
docker run --rm --user "$(id -u):$(id -g)" --memory "${BUILD_MEMORY:-768m}" -e HOME=/tmp -e npm_config_cache=/tmp/npm-cache -e NODE_OPTIONS=--max-old-space-size=512 --mount "type=bind,src=$source_dir,dst=/app" --mount "type=bind,src=$repo_dir,dst=/mod,readonly" -w /app node:22-alpine sh -c 'if [ ! -d node_modules/ws ]; then npm ci --omit=dev; fi; node /mod/mods/party/generate-data.mjs /app && node --test test/party-mods.test.js test/protocol-seats.test.js test/lobby.test.js test/lobby-loadout.test.js test/room-rhine-profile.test.js test/ui/data-profile.test.js test/content/rhine.test.js test/content/rhine_new_kits.test.js test/content/rhine_equipment.test.js test/match/rhineResearch.test.js test/match/runner-profile.test.js test/match/lobby-integration.test.js test/content/relics.test.js test/content/relic-balance.test.js test/match/relics.test.js test/ui/relics.test.js test/content/makoto.test.js test/content/narant.test.js test/content/extra6.test.js test/sim/damage-board.test.js test/match/damage-board.test.js test/ui/damage-board.test.js test/match/party-runtime.test.js'
